def normalize_iban(iban: str) -> str:
    # Remove only ASCII spaces and uppercase; no validation.
    if not isinstance(iban, str):
        raise ValueError("iban must be a string")
    return iban.replace(" ", "").upper()

def validate_iban(iban: str) -> bool:
    # Non-strings are invalid, never raise.
    if not isinstance(iban, str):
        return False
    s = iban.replace(" ", "").upper()
    if len(s) < 4:
        return False
    country = s[:2]
    # Country -> exact total length table.
    lengths = {"AD": 24, "AT": 20, "BE": 16, "CH": 21, "DE": 22, "ES": 24, "FR": 27, "GB": 22, "IE": 22, "IT": 27, "LU": 20, "NL": 18, "NO": 15, "PL": 28, "PT": 25, "SE": 24}
    if country not in lengths:
        return False
    if len(s) != lengths[country]:
        return False
    # Structure: CC letters, 2 digits, rest alphanumerics.
    if not ("A" <= s[0] <= "Z" and "A" <= s[1] <= "Z"):
        return False
    if not ("0" <= s[2] <= "9" and "0" <= s[3] <= "9"):
        return False
    for ch in s[4:]:
        if not (("A" <= ch <= "Z") or ("0" <= ch <= "9")):
            return False
    # Mod-97: move first 4 to end, A=10..Z=35, require % 97 == 1.
    rearranged = s[4:] + s[:4]
    rem = 0
    for ch in rearranged:
        if "0" <= ch <= "9":
            rem = (rem * 10 + (ord(ch) - 48)) % 97
        else:
            # ch is A-Z per structure check above.
            n = ord(ch) - 55
            rem = (rem * 100 + n) % 97
    return rem == 1
